def smallest_change(arr):
    def is_palindromic(sub_arr):
        return sub_arr == sub_arr[::-1]

    def count_changes(sub_arr):
        changes = 0
        for i in range(len(sub_arr) // 2):
            changes += abs(sub_arr[i] - sub_arr[-i - 1])
        return changes

    if is_palindromic(arr):
        return 0

    middle = len(arr) // 2
    left = arr[:middle]
    right = arr[middle + len(arr) % 2:]

    return min(count_changes(left), count_changes(right))

